create or replace function public.sales_charge_catalog_put_v610(p_tenant_id uuid,p_location_id uuid,p_device_id uuid,p_charge_id uuid,p_code text,p_name text,p_charge_kind text,p_service_variant_id uuid,p_default_quantity numeric,p_auto_dine_in boolean,p_auto_takeaway boolean,p_auto_delivery boolean,p_active boolean) returns uuid language plpgsql security definer set search_path=public,private,pg_temp as $$ declare v_id uuid; begin perform private.erp_validate_vertical_device_scope(p_tenant_id,p_location_id,p_device_id,'restaurant','operate'); if not(private.erp_user_is_owner(p_tenant_id) or private.erp_has_permission(p_tenant_id,'restaurant.manage') or private.erp_has_permission(p_tenant_id,'sales.manage')) then raise exception 'Manage permission required'; end if; perform private.sales_charge_catalog_assert_v610(p_tenant_id,p_service_variant_id); if p_charge_id is null then insert into public.sales_charge_catalog_v610(tenant_id,code,name,charge_kind,service_variant_id,default_quantity,auto_apply_dine_in,auto_apply_takeaway,auto_apply_delivery,active) values(p_tenant_id,upper(trim(p_code)),trim(p_name),lower(trim(p_charge_kind)),p_service_variant_id,p_default_quantity,coalesce(p_auto_dine_in,false),coalesce(p_auto_takeaway,false),coalesce(p_auto_delivery,false),coalesce(p_active,true)) returning id into v_id; else update public.sales_charge_catalog_v610 set code=upper(trim(p_code)),name=trim(p_name),charge_kind=lower(trim(p_charge_kind)),service_variant_id=p_service_variant_id,default_quantity=p_default_quantity,auto_apply_dine_in=coalesce(p_auto_dine_in,false),auto_apply_takeaway=coalesce(p_auto_takeaway,false),auto_apply_delivery=coalesce(p_auto_delivery,false),active=coalesce(p_active,true),updated_at=now() where id=p_charge_id and tenant_id=p_tenant_id returning id into v_id; end if; if v_id is null then raise exception 'Commercial charge not found'; end if; return v_id; end; $$;;
